VALUES
('pmbrmbe_0095', 'pmbrmbe', '0095', '95', 'PMBR Early Bird MBE 2007', 'Torts', '95', '', 'Larry, a plumber, left a gas line open, causing explosion.', '(A) Larry is strictly liable.', '(B) Larry is liable for negligence.', '(C) Larry is not liable unless warned.', '(D) Larry is not liable if explosion was unforeseeable.', 'B', '', 'pmbrmbe_0095', 0, NULL),
('pmbrmbe_0096', 'pmbrmbe', '0096', '96', 'PMBR Early Bird MBE 2007', 'Torts', '96', '', 'Tom was injured by an escalator in a department store.', '(A) Store is strictly liable.', '(B) Store is liable if escalator was defective or poorly maintained.', '(C) Store is not liable unless warned.', '(D) Store is not liable if Tom was careless.', 'B', '', 'pmbrmbe_0096', 0, NULL),
('pmbrmbe_0097', 'pmbrmbe', '0097', '97', 'PMBR Early Bird MBE 2007', 'Torts', '97', '', 'Jill, a bystander, was hit by debris from a demolition site.', '(A) Demolition company is strictly liable.', '(B) Demolition company is not liable unless negligent.', '(C) Demolition company is not liable if site was fenced.', '(D) Demolition company is not liable if Jill ignored warning signs.', 'A', '', 'pmbrmbe_0097', 0, NULL),
('pmbrmbe_0098', 'pmbrmbe', '0098', '98', 'PMBR Early Bird MBE 2007', 'Torts', '98', '', 'Pam sued after tripping on cracked sidewalk outside a store.', '(A) Store is strictly liable.', '(B) Store is not liable unless it owned sidewalk.', '(C) Store is liable if it controlled sidewalk.', '(D) Store is not liable if Pam was careless.', 'C', '', 'pmbrmbe_0098', 0, NULL),
('pmbrmbe_0099', 'pmbrmbe', '0099', '99', 'PMBR Early Bird MBE 2007', 'Torts', '99', '', 'Nick, a repairman, was hurt by a faulty elevator in an office building.', '(A) Owner is strictly liable.', '(B) Owner is liable only if negligent.', '(C) Owner is not liable unless warned.', '(D) Owner is not liable if Nick misused elevator.', 'B', '', 'pmbrmbe_0099', 0, NULL),
('pmbrmbe_0100', 'pmbrmbe', '0100', '100', 'PMBR Early Bird MBE 2007', 'Torts', '100', '', 'Rachel a hotel guest, was burned by hot water in her shower.', '(A) Hotel is strictly liable.', '(B) Hotel is liable if it failed to regulate temperature.', '(C) Hotel is not liable unless warned.', '(D) Hotel is not liable if Rachel was careless.', 'B', '', 'pmbrmbe_0100', 0, NULL),
('pmbrmbe_0101', 'pmbrmbe', '0101', '101', 'PMBR Early Bird MBE 2007', 'Contracts', '1', '', 'Paul offered to sell a car to Dan for $5,000. Dan replied, "I will pay $4,500."', '(A) "There is a contract at $5,000."', '(B) There is a contract at $4,500.', '(C) There is no contract.', '(D) Paul must accept $4,500.', 'C', '', 'pmbrmbe_0101', 0, NULL),
('pmbrmbe_0102', 'pmbrmbe', '0102', '102', 'PMBR Early Bird MBE 2007', 'Contracts', '2', '', 'Anna mailed an offer to Ben on May 1. Ben mailed his acceptance on May 2, but Anna revoked her offer on May 3 before receiving the acceptance.', '(A) There is a contract.', '(B) There is no contract.', '(C) Anna''s revocation is effective.', '(D) The offer lapsed.', 'A', '', 'pmbrmbe_0102', 0, NULL),
('pmbrmbe_0105', 'pmbrmbe', '0105', '105', 'PMBR Early Bird MBE 2007', 'Contracts', '5', '', 'A signed option contract to buy a house was supported by $10 consideration.', '(A) The option is revocable.', '(B) The option is irrevocable during the stated period.', '(C) The option is void for lack of consideration.', '(D) The option is enforceable only by the seller.', 'B', '', 'pmbrmbe_0105', 0, NULL),
('pmbrmbe_0106', 'pmbrmbe', '0106', '106', 'PMBR Early Bird MBE 2007', 'Contracts', '6', '', 'Frank agreed to paint Ann''s house for $1,000. After finishing, Ann refused to pay.', '(A) Frank can recover in quantum meruit.', '(B) Frank has no remedy.', '(C) Frank can only sue for breach.', '(D) Ann can rescind the contract.', 'A', '', 'pmbrmbe_0106', 0, NULL),
('pmbrmbe_0110', 'pmbrmbe', '0110', '110', 'PMBR Early Bird MBE 2007', 'Contracts', '10', '', 'Ed promised to sell land to Alice, but the agreement was not in writing.', '(A) Ed can enforce the agreement.', '(B) Alice can enforce the agreement.', '(C) The contract is unenforceable under the Statute of Frauds.', '(D) The contract is void.', 'C', '', 'pmbrmbe_0110', 0, NULL),
('pmbrmbe_0111', 'pmbrmbe', '0111', '111', 'PMBR Early Bird MBE 2007', 'Contracts', '11', '', 'Leo, a minor, signed a contract to buy a car.', '(A) The contract is void.', '(B) The contract is voidable by Leo.', '(C) The contract is enforceable.', '(D) The contract is voidable by seller.', 'B', '', 'pmbrmbe_0111', 0, NULL),
('pmbrmbe_0112', 'pmbrmbe', '0112', '112', 'PMBR Early Bird MBE 2007', 'Contracts', '12', '', 'Sam paid Sue to deliver goods on June 1, but Sue delivered June 10.', '(A) Sam must accept late delivery.', '(B) Sam may reject the goods.', '(C) Sam is liable for breach.', '(D) Sue may rescind.', 'B', '', 'pmbrmbe_0112', 0, NULL),
('pmbrmbe_0113', 'pmbrmbe', '0113', '113', 'PMBR Early Bird MBE 2007', 'Contracts', '13', '', 'Ned promised to sell a rare coin to Ron, but sold it to Lisa instead.', '(A) Ron can recover the coin.', '(B) Ron can sue for damages.', '(C) Ron can void the sale to Lisa.', '(D) Lisa has no rights.', 'B', '', 'pmbrmbe_0113', 0, NULL),
('pmbrmbe_0114', 'pmbrmbe', '0114', '114', 'PMBR Early Bird MBE 2007', 'Contracts', '14', '', 'Greg agreed to paint Amy''s house, but Amy refused to let him.', '(A) Greg can recover full contract price.', '(B) Greg can sue for breach.', '(C) Greg has no remedy.', '(D) Amy is excused from performance.', 'B', '', 'pmbrmbe_0114', 0, NULL),
('pmbrmbe_0117', 'pmbrmbe', '0117', '117', 'PMBR Early Bird MBE 2007', 'Contracts', '17', '', 'Martha agreed in writing to sell land to Ed, but failed to deliver the deed.', '(A) Ed can force Martha to perform.', '(B) Ed has no remedy.', '(C) Ed can sue only for damages.', '(D) Martha can rescind.', 'A', '', 'pmbrmbe_0117', 0, NULL),
('pmbrmbe_0118', 'pmbrmbe', '0118', '118', 'PMBR Early Bird MBE 2007', 'Contracts', '18', '', 'Brian made an oral contract to buy goods worth $600.', '(A) Contract is enforceable.', '(B) Contract is unenforceable under Statute of Frauds.', '(C) Contract is valid.', '(D) Brian must pay.', 'B', '', 'pmbrmbe_0118', 0, NULL),
('pmbrmbe_0120', 'pmbrmbe', '0120', '120', 'PMBR Early Bird MBE 2007', 'Contracts', '20', '', 'Kyle agreed to build a house for Mary by August 1, but finished on August 10.', '(A) Mary must accept.', '(B) Mary may recover damages.', '(C) Mary can rescind.', '(D) Kyle has no remedy.', 'B', '', 'pmbrmbe_0120', 0, NULL),
('pmbrmbe_0121', 'pmbrmbe', '0121', '121', 'PMBR Early Bird MBE 2007', 'Contracts', '21', '', 'Clara agreed to sell a boat to Tom, but before delivery the boat was stolen.', '(A) Clara must deliver a substitute boat.', '(B) Tom must accept the loss.', '(C) Clara is excused due to impossibility.', '(D) Tom can sue for damages.', 'C', '', 'pmbrmbe_0121', 0, NULL),
('pmbrmbe_0123', 'pmbrmbe', '0123', '123', 'PMBR Early Bird MBE 2007', 'Contracts', '23', '', 'A builder contracted to construct a house, but the buyer refused to pay for extras.', '(A) The builder can recover only for agreed extras.', '(B) The builder can recover for extras if ordered by buyer.', '(C) The builder cannot recover for extras.', '(D) The builder must finish house before suing.', 'B', '', 'pmbrmbe_0123', 0, NULL),
('pmbrmbe_0124', 'pmbrmbe', '0124', '124', 'PMBR Early Bird MBE 2007', 'Contracts', '24', '', 'A signed contract for the sale of land omitted the purchase price.', '(A) Contract is enforceable.', '(B) Contract is void.', '(C) Court can supply a reasonable price.', '(D) The parties must renegotiate.', 'C', '', 'pmbrmbe_0124', 0, NULL),
('pmbrmbe_0130', 'pmbrmbe', '0130', '130', 'PMBR Early Bird MBE 2007', 'Contracts', '30', '', 'Pat signed a contract with blank terms, intending to fill in later.', '(A) Contract is enforceable as written.', '(B) Contract is unenforceable for indefiniteness.', '(C) Court can supply missing terms.', '(D) Contract is void.', 'B', '', 'pmbrmbe_0130', 0, NULL),
('1', 'mbe', 'mbe_0001', 'prompt_0026', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'criminal', '46', '', 'CRIMINAL LAW Question 16 Simpson and two others were indicted on felony charges for electronic theft of bank accounts. Simpson protested that he was inno- cent and wanted to prove it at trial, but agreed to discuss a plea bargain with the district attorney. The district attorney indicated that he would also charge Simpson with additional theft by computer offenses if Simpson insisted on going to trial, but that if he pleaded guilty to the one charge and agreed to testify against his co- defendants at their trial, the prosecution would recommend probation only. Because of the risk of jail time if he was convicted of any of the additional offenses, Simpson agreed. When Simpson appeared in court, the judge informed him of the nature of the charge and the potential punishment, and that Simpson was waiving his right to trial by pleading guilty. She asked if his plea was voluntary and he replied that it was the best deal that he could get, but that he was really innocent of the crime charged. The judge nevertheless accepted the plea, reserving sentencing until Simpson testified against his co-defendants. Just before trial of Simpson’s co-defendants, they pleaded guilty and provided additional information of Simpson’s central role in the crime and in additional computer theft offenses. At Simpson’s sentencing, the prosecution introduced the testimony of Simpson’s co- defendants and asked the judge to impose a jail term. The judge sentenced Simpson to five years in prison for the crime to which he pleaded guilty. Simpson appeals his sentence, raising the following arguments: I. The prosecution threatened to bring addi- tional charges when Simpson indicated that he was going to exercise his right to go to trial. Il. The judge accepted Simpson’s guilty plea despite his claim of innocence. Ill. The prosecution did not adhere to the plea bargain after Simpson’s co-defendants pleaded guilty. Which of the above arguments provide a valid basis for vacating Simpson’s guilty plea an', 'The city of Briggs and the state of Riverfront are separate sovereigns.', 'The state charge requires the proving of a fact not required by the municipal charge.', 'Chaven’s trial in municipal court had not yet reached the stage where jeopardy attaches.', 'The dismissal of the case in municipal court was based on a technicality that did not go to the merits of the case. STOP ag yen yay ororr BAR REVIEW 2 ©@®@OO 3 ©®OO', 'D', '', '', 0, ''),
('2', 'mbe', 'mbe_0002', 'prompt_0028', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'evidence', '50', '', 'EVIDENCE Question 4 On an icy day, a vehicle driven by Doug struck Peter’s car in the rear, smashing a taillight and denting Peter’s bumper. Before Peter could say anything, Doug rushed out of his car and told Peter, “Look, if you’! take $500 for the damage, I’m sure my insurance company will pay for it.” Peter refused and sued Doug for damage to his car and minor personal injuries. Peter wishes to testify as to Doug’s statement at the time of the accident. Doug objects. Should the court allow Doug’s statement to be admitted?', 'The issue should be decided by the judge after hearing evidence from Greed’s attor- ney and Johnson’s attorney outside the presence of the jury.', 'The issue should be decided by the judge after hearing evidence from Greed’s attor- ney and Johnson’s attorney and may be conducted in the presence of the jury.', 'The issue should be decided by the jury after hearing evidence from both sides.', 'The issue should be decided by the judge after hearing evidence from both sides outside the presence of the jury, but if the document is admitted by the judge, Johnson may present evidence challenging that finding while presenting his case, and the ultimate decision rests with the jury. GO ON TO THE NEXT PAGE ite', 'B', '', '', 0, ''),
('3', 'mbe', 'mbe_0003', 'prompt_0029', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'evidence', '52', '', 'EVIDENCE Question 10 Debra’s car struck Peter, a pedestrian, and sped away from the scene of the accident. The car was linked to Debra, but she denies that she was driving the car when Peter was hit and injured. Peter sued Debra for his injuries. The only eyewitness, other than Peter, was Willie, a six-year-old child. During the trial, Peter put Willie on the stand, and Willie testified that he saw Debra driving the car that hit Peter. The defense elected not to cross-examine Willie. The plaintiff’s next witness was Schrinkov, a child psychologist. Schrinkov, who had never met Willie before, was prepared to testify that, based on his observations of Willie on the witness stand, it was highly probable that Willie was telling the truth. Schrinkov was qualified as an expert witness with many years of experience dealing with children. However, the defense objected to any questions regarding the veracity of Willie. Should Schrinkov be allowed to testify about Willie?', 'No, unless there has been no other evi- dence about overheating of the tanks presented by Julio.', 'No, because Julio’s testimony is inadmis- sible hearsay.', 'Yes, because Julio’s testimony is evidence of a fact in issue.', 'Yes, because Julio’s testimony is evidence of a verbal act. GO ON TO THE NEXT PAGE', 'B', '', '', 0, '')
